function HeroSelectionManagerImpl:GetUGCHeroData(HeroID)
    assert(self.bInitialized)

    if HeroID and next(self.HeroDataMap) then
        if self.HeroDataMap[HeroID] then
            return self.HeroDataMap[HeroID]
        elseif self.IdxToHeroIDMap[HeroID] and self.HeroDataMap[self.IdxToHeroIDMap[HeroID]] then
