function HeroSelectionManagerImpl:GetDisplayedHeroDataList()
    local Result = {}

    for _, v in pairs(self:GetAllUGCHeroData()) do
        local HeroUIData = self:GetUGCHeroUIData(v.ID)
        local IsShow = HeroUIData and HeroUIData.IsShow or false

        if IsShow then
            table.insert(Result, v)
        end
    end

    if Result then
        table.sort(Result, function(a, b)
            local PriorityA = self:GetUGCHeroUIData(a.ID).SortPriority
            local PriorityB = self:GetUGCHeroUIData(b.ID).SortPriority
            return PriorityA < PriorityB
        end)
    end

    return Result
end

function HeroSelectionManagerImpl:GetFirstAvailableHeroID()
    assert(self.bInitialized)
    ---@param v Hero
    for _, v in pairs(self:GetDisplayedHeroDataList()) do
        if self:IsHeroPermanentFree(v.ID) then
            return v.ID
        end
    end
    return -1
end

