function HeroSelectionManagerImpl:IsHeroTimeLimitedFree(HeroID)
    assert(self.bInitialized)

    -- 付费类型英雄，计算限免逻辑
    if self.HeroFreeDebugData then
        ugcprint(string.format("[HeroSelection] IsHeroTimeLimitedFree: HeroFreeDebugData is enabled, current time is %s.", self.HeroFreeDebugData))
    end

    local Data = self:GetUGCHeroFreeConfigData(HeroID)

    if not Data then
        return false
    end

    -- 1. 获取服务器时间
    -- 2. 转换成 KismetMathLibrary 支持的格式 --> FDateTime
    local ServerTime = UGCGameSystem.GetServerTimeSec()
    local Now = ConvertToFDateTime(ServerTime) or KismetMathLibrary.Now()
    local StartYear, StartMonth, StartDay, StarHour, StartMinute, StartSec = KismetMathLibrary.BreakDateTime(Data.StartDate)
    local NowYear, NowMonth, NowDay, NowHour, NowMinute, NowSec = KismetMathLibrary.BreakDateTime(Now)

    -- 1. 判断是否在有效期内
    if KismetMathLibrary.Less_DateTimeDateTime(Data.StartDate, Now) and KismetMathLibrary.Less_DateTimeDateTime(Now, Data.EndDate) then
        if Data.FreeType == EHeroFreeType.Monthly then
            local TempDateTime
            -- 处理月份：
            if NowDay >= StartDay then
                -- a. NowDay > StartDay 在同月份，无需处理
                TempDateTime = KismetMathLibrary.MakeDateTime(NowYear, NowMonth, StartDay, StarHour, StartMinute, StartSec, 0)
            else
                -- b. NowDay < StartDay 不在同月份，视作跨月，需减去一个月
                local TempMonth = NowMonth - 1  -- [1, 12]
                local TempYear = NowYear
                -- 如果跨年了，就必须减去一年
                if TempMonth == 0 then TempMonth = 12 TempYear = TempYear - 1 end
                TempDateTime = KismetMathLibrary.MakeDateTime(TempYear, TempMonth, StartDay, StarHour, StartMinute, StartSec, 0)
            end
            local TimeSpan = KismetMathLibrary.Subtract_DateTimeDateTime(Now, TempDateTime)
            local DaysOffsetByMonth = KismetMathLibrary.GetTotalDays(TimeSpan)
            ugcprint(string.format("[HeroSelection] IsHeroTimeLimitedFree: Now = %s, TempDateTime = %s, TimeSpan = %s, DaysOffsetByMonth = %f", Now, TempDateTime, TimeSpan, DaysOffsetByMonth))
            if DaysOffsetByMonth > 31 or DaysOffsetByMonth < 0 then
                ugcprint("[HeroSelection] IsHeroTimeLimitedFree: DaysOffsetByMonth is invalid, limited free will not be applied.")
                return false
            end
            if DaysOffsetByMonth > 0 and DaysOffsetByMonth <= Data.DurationDays then
                return true
            end
        elseif Data.FreeType == EHeroFreeType.Weekly then
            local TimeSpan = KismetMathLibrary.Subtract_DateTimeDateTime(Now, Data.StartDate)
            local CycleDays = 7 * Data.CycleNumber
            local DaysOffsetByWeek = KismetMathLibrary.GetTotalDays(TimeSpan) % CycleDays
            ugcprint(string.format("[HeroSelection] IsHeroTimeLimitedFree: Now = %s, TimeSpan = %s, CycleDays = %d, DaysOffsetByWeek = %f", Now, TimeSpan, CycleDays, DaysOffsetByWeek))
            if DaysOffsetByWeek <= Data.DurationDays then
                return true
            end
        elseif Data.FreeType == EHeroFreeType.Daily then
            local TimeSpan = KismetMathLibrary.Subtract_DateTimeDateTime(Now, Data.StartDate)
            local CycleDays = Data.CycleNumber
            local DaysOffsetByNDays = KismetMathLibrary.GetTotalDays(TimeSpan) % CycleDays
            ugcprint(string.format("[HeroSelection] IsHeroTimeLimitedFree: Now = %s, TimeSpan = %s, CycleDays = %d, DaysOffsetByNDays = %f", Now, TimeSpan, CycleDays, DaysOffsetByNDays))
            if DaysOffsetByNDays <= Data.DurationDays then
                return true
            end
        elseif Data.FreeType == EHeroFreeType.Fixed then
            ugcprint("[HeroSelection] IsHeroTimeLimitedFree: Fixed free type")
            return true
        end
    end

    return false
end

function HeroSelectionManagerImpl:IsHeroPermanentFree(HeroID)
    if not self.bInitialized then
        ugcprint("[HeroSelection] HeroSelectionManagerImpl:GetAllUGCHeroData(): HeroSelectionManagerImpl not initialized.")
        return false
    end

    -- 免费类型英雄，直接返回 true
    local HeroUIData = self:GetUGCHeroUIData(HeroID)
    if HeroUIData and HeroUIData.IsFree then
        return true
    end

    return false
end

function HeroSelectionManagerImpl:IsHeroLocked(HeroID)
    if not self.bInitialized then
        ugcprint("[HeroSelection] HeroSelectionManagerImpl:IsHeroLocked(): HeroSelectionManagerImpl not initialized.")
        return false
    end

    if not HeroID then
        ugcprint("[HeroSelection] HeroSelectionManagerImpl:IsHeroLocked(): param HeroID is nil.")
        return false
    end

    -- 英雄是否免费
    if self:IsHeroFree(HeroID) then
        return false
    end

    -- 付费英雄是否已购买
    if HeroSelectionShopProxy:IsHeroPurchased(HeroID) then
        return false
    end

    -- 付费、未购买、非周免英雄
    return true
end

