function HeroSelectionManagerImpl:RequestSelectHero(HeroID)
    assert(self.bInitialized and not UGCGameSystem.IsServer())
    print("[HeroSelection] RequestSelectHero(" .. tostring(HeroID) .. ")")
    local PC = UGCGameSystem.GetLocalPlayerController()
    local PK = UGCGameSystem.GetLocalPlayerKey()
    UnrealNetwork.CallUnrealRPC(PC, self.HeroSelectionActor, "Server_SelectHero", PK, HeroID)
end

function HeroSelectionManagerImpl:SelectHero(PlayerKey, HeroID)
    assert(self.bInitialized and UGCGameSystem.IsServer() and PlayerKey and HeroID)
    print("[HeroSelection] SelectHero(" .. tostring(PlayerKey) .. ", " .. tostring(HeroID) .. ")")

    self.HeroSelectionActor:SetSelectedHeroID(PlayerKey, HeroID)
    self.OnHeroSelected(PlayerKey, HeroID)
end

function HeroSelectionManagerImpl:SelectCurrentFocusedHero()
    assert(self.bInitialized and not UGCGameSystem.IsServer())
    print("[HeroSelection] SelectCurrentFocusedHero()")
    if self:GetCurrentFocusedHeroID() then
        self:RequestSelectHero(self:GetCurrentFocusedHeroID())
    end
end

function HeroSelectionManagerImpl:IsHeroCanSelect(HeroID)
    assert(self.bInitialized and not UGCGameSystem.IsServer())

    if not HeroID then
        print("[HeroSelection] IsHeroCanSelect(HeroID): param HeroID is nil, will use CurrentFocusedHeroID instead by default.")
    end

    local F = HeroID or self:GetCurrentFocusedHeroID()-- 入参视为当前选中的英雄
    local S = self:GetSelectedHeroID(UGCGameSystem.GetLocalPlayerKey()) -- TODO: Make player key as param

    if F and S then
        -- 选中的英雄和已选择的英雄不同时
        return F ~= S
    elseif F and not S then
        -- 还没选择任何英雄时
        return true
    elseif not F then
        -- 没有选中任何英雄？错误！
        print("[HeroSelection] Warning: IsHeroCanSelect(): No focused hero! Nothing can be selected")
        return false
    end
end

function HeroSelectionManagerImpl:ApplySelectedHeroData(PlayerKey, HeroID)
    assert(self.bInitialized and UGCGameSystem.IsServer() and PlayerKey)
    print("[HeroSelection] ApplySelectedHeroData(" .. tostring(PlayerKey) .. ", " .. tostring(HeroID) .. ")")

    HeroID = HeroID or self:GetSelectedHeroID(PlayerKey)
    if not HeroID or HeroID == -1 then
        print("[HeroSelection] Warning: GetCurrentSelectedHeroID() is nil, will use HeroID instead, this param will be deprecated in the future.")
        return
    end

    local CurrentHeroData = self:GetUGCHeroData(HeroID)
    if not CurrentHeroData then
        print("[HeroSelection] Error: CurrentHeroData is nil, apply failed!")
        return
    end

    local TargetPawn = UGCGameSystem.GetPlayerPawnByPlayerKey(PlayerKey)
    if not TargetPawn then
        print("[HeroSelection] Error: TargetPawn is nil, apply failed!")
        return
    end

    if CurrentHeroData.HeroMeshPath then
        if TargetPawn then
            local Path = UGCObjectUtility.GetPathBySoftObjectPath(CurrentHeroData.HeroMeshPath)
            print("[HeroSelection] Apply Mesh, Path = " .. tostring(Path))
            local NewAvatarMesh = UE.LoadObject(Path)
            TargetPawn:UGCRecoverAvatarMesh()
            UGCTimerUtility.CreateLuaTimer(0.1, function() TargetPawn:UGCSetCharacterMeshCoverAvatarMesh(NewAvatarMesh) end)
        else
            print("[HeroSelection] Warning: Apply Mesh, TargetPawn is nil!")
        end
    end

    local HeroSkills = CurrentHeroData.HeroSkills
    local PersistClientStateComponent = TargetPawn:GetPlayerPersistClientState()
    if HeroSkills and PersistClientStateComponent then
        for _, Skill in ipairs(HeroSkills) do
            print("[HeroSelection] Apply Skill = " .. tostring(Skill))
            if PersistClientStateComponent then
                PersistClientStateComponent:ApplyPersistEffectDataByClass(Skill, -1.0)
            end
        end
    else
        print("[HeroSelection] Warning: Apply skill failed, HeroSkills or PersistClientStateComponent is nil!")
    end

    local HeroBuffs = CurrentHeroData.HeroBuffs
    if HeroBuffs and PersistClientStateComponent then
        for _, Buff in ipairs(HeroBuffs) do
            print("[HeroSelection] Apply Buff = " .. tostring(Buff))
            if PersistClientStateComponent then
                PersistClientStateComponent:ApplyPersistEffectDataByClass(Buff, -1.0)
            end
        end
    else
        print("[HeroSelection] Warning: Apply Buff, HeroBuffs or PersistClientStateComponent is nil!")
    end

    local HeroAttributes = CurrentHeroData.HeroAttributes
    if HeroAttributes then
        for _, Attribute in ipairs(HeroAttributes) do
            print("[HeroSelection] Apply Attribute = " .. tostring(Attribute.GameAttribute.AttributeName))
            UGCAttributeSystem.SetGameAttributeValue(TargetPawn, Attribute.GameAttribute.AttributeName, Attribute.InitialValue)
        end
    else
        print("[HeroSelection] Warning: Apply Attribute failed, HeroAttributes is nil!")
    end
end

