function HeroSelectionManagerImpl:Init(InHeroSelectionActor)
    print("[HeroSelection] Init(" .. tostring(InHeroSelectionActor) .. ")")
    if self.bInitialized then
        print("[HeroSelection] Warning: HeroSelectionManagerImpl:Init(): already initialized.")
        return
    end

    if not InHeroSelectionActor then
        ugcprint("[HeroSelection] HeroSelectionManagerImpl:init(): HeroSelectionActor is nil, init failed.")
        return
    end

    self.HeroSelectionActor = InHeroSelectionActor
    self:UpdateCachedVariables()

    if not self:InitHeroData() then
        ugcprint("[HeroSelection] HeroSelectionManagerImpl:Init(): HeroTable is nil")
        return
    end

    if not self:InitHeroUIData() then
        ugcprint("[HeroSelection] HeroSelectionManagerImpl:Init(): InitHeroUIData is nil")
        return
    end

    if not self:InitHeroAbilityLabelData() then
        ugcprint("[HeroSelection] HeroSelectionManagerImpl:Init(): InitHeroAbilityLabelData is nil")
        return
    end

    if not self:InitHeroFreeConfigData() then
        ugcprint("[HeroSelection] HeroSelectionManagerImpl:Init(): InitHeroFreeConfigData is nil")
        return
    end

    if not HeroSelectionShopProxy.bInitialized then
        HeroSelectionShopProxy:Init(self.PlayerController, self.HeroUIDataArr)
    end
    self.bInitialized = true
    self.OnInitialized()
end

function HeroSelectionManagerImpl:InitWidget()
    assert(self.bInitialized and not UGCGameSystem.IsServer())
    print("[HeroSelection] InitWidget()")
    local Path = UGCObjectUtility.GetPathBySoftObjectPath(self.HeroSelectionActor.MainWidgetClass)
    UGCWidgetManagerSystem.CreateWidgetAsync(Path, function(Widget)
        Widget:AddToViewport()
        UGCWidgetManagerSystem.HideWidget(Widget)
    end)
end

function HeroSelectionManagerImpl:InitHeroData()
    ugcprint("[HeroSelection] HeroSelectionManagerImpl:InitHeroData()")
    local HeroTable = UGCGameSystem.GetTableData(self.HeroSelectionActor.UGCHeroTable)
    self.HeroDataMap = {}
    self.IdxToHeroIDMap = {}

    local SortIdx = 1

    if HeroTable ~= nil then
        for _, v in pairs(HeroTable) do
            ---@type Hero
            local HeroData = {}

            -- 英雄 ID
            HeroData.ID = v.ID
            -- 英雄名称
            HeroData.Name = v.Name
            -- 英雄描述
            HeroData.Desc = v.Desc
            -- 图标资源引用
            HeroData.Icon = v.Icon
            -- Skill（数组）
            HeroData.HeroSkills = v.HeroSkills:Copy()
            -- Buff（数组）
            HeroData.HeroBuffs = v.HeroBuffs:Copy()
            -- 属性（数组）
            HeroData.HeroAttributes = v.HeroAttributes:Copy()
            -- 骨骼体软引用路径
            HeroData.HeroMeshPath = v.HeroMeshPath:Copy()

            self.HeroDataMap[v.ID] = HeroData
            self.IdxToHeroIDMap[SortIdx] = v.ID

            ugcprint(string.format("[HeroSelection] Init hero data: id = %s, name = %s", v.ID, v.Name))

            SortIdx = SortIdx + 1
        end
        return true
    end
    return false
end

function HeroSelectionManagerImpl:InitHeroUIData()
    ugcprint("[HeroSelection] HeroSelectionManagerImpl:InitHeroUIData()")

    local HeroUIDataTable = UGCGameSystem.GetTableData(self.HeroSelectionActor.UGCHeroUITable)

    if HeroUIDataTable ~= nil then
        for _, v in pairs(HeroUIDataTable) do
            ---@type HeroUI
            local HeroUIData = {}

            HeroUIData.ID = v.ID
            HeroUIData.HeroID = v.HeroID
            HeroUIData.ProductID = v.ProductID
            HeroUIData.SortPriority = v.SortPriority
            HeroUIData.IsShow = v.IsShow
            HeroUIData.IsFree = v.IsFree
            HeroUIData.HeroDetail1 = v.HeroDetail1
            HeroUIData.HeroAbilityLabelIsIcon = v.HeroAbilityLabelIsIcon
            HeroUIData.HeroDetail3 = v.HeroDetail3

            table.insert(self.HeroUIDataArr, HeroUIData)
            ugcprint(string.format("[HeroSelection] Init hero ui data: id = %s, hero = %s, HeroAbilityLabelIsIcon = %s", v.ID, v.HeroID, v.HeroAbilityLabelIsIcon))
        end
        return true
    end
    return false
end

