function HeroSelectionManagerImpl:OpenMainWidget()
    assert(self.bInitialized)
    print("[HeroSelection] OpenMainWidget()")

    -- 设置玩家镜头到展示的英雄模型上
    self.PlayerController:SetViewTargetWithBlend(self.HeroSelectionActor)

    -- 隐藏和平的主界面UI、射击UI，保留设置和聊天按钮
    local MainControlPanel = GameBusinessManager.GetWidgetFromName(ingame, "MainControlPanelTochButton_C");
    if MainControlPanel ~= nil then
        UGCWidgetManagerSystem.AddWidgetHiddenLayer(MainControlPanel.MainControlBaseUI)
        UGCWidgetManagerSystem.AddWidgetHiddenLayer(MainControlPanel.ShootingUIPanel)

        local PC = UGCGameSystem.GetLocalPlayerController()
        PC:SetVirtualJoystickVisibility(false);

        if PC then
            UGCWidgetManagerSystem.SetCrosshairVisibility(false)
        end
    else
        print("[HeroSelection] Warning: CaptureAndHoldUIManager:InitBaseUI MainControlPanel == nil!");
    end

    -- 开启滑动检测
    self:StartDetectTouch()

    -- 调试用，打印目前关键的英雄数据到 log 中
    self:DumpHeroData()

    local PC = UGCGameSystem.GetLocalPlayerController()
    PC.OnTouchInterfaceChangedDelegate:Add(self.OnTouchInterfaceChanged, self)

    self.OnMainWidgetOpened()
end

function HeroSelectionManagerImpl:CloseMainWidget()
    assert(self.bInitialized)
    print("[HeroSelection] CloseMainWidget()")

    -- 还原摄像机到玩家角色
    self.PlayerController:SetViewTargetWithBlend(self.PlayerPawn)

    -- 还原和平的主界面UI、射击UI，保留设置和聊天按钮
    local MainControlPanel = GameBusinessManager.GetWidgetFromName(ingame, "MainControlPanelTochButton_C");
    if MainControlPanel ~= nil then
        UGCWidgetManagerSystem.SubWidgetHiddenLayer(MainControlPanel.MainControlBaseUI)
        UGCWidgetManagerSystem.SubWidgetHiddenLayer(MainControlPanel.ShootingUIPanel)

        local PC = UGCGameSystem.GetLocalPlayerController()
        PC:SetVirtualJoystickVisibility(true);

        if PC then
            UGCWidgetManagerSystem.SetCrosshairVisibility(true)
        end
    else
        print("[HeroSelection] Warning: CaptureAndHoldUIManager:InitBaseUI MainControlPanel == nil!");
    end

    -- 关闭滑动检测
    self:StopDetectTouch()

    local PC = UGCGameSystem.GetLocalPlayerController()
    PC.OnTouchInterfaceChangedDelegate:Remove(self.OnTouchInterfaceChanged, self)

    self.OnMainWidgetClosed()
end

function HeroSelectionManagerImpl:OnTouchInterfaceChanged()
    ugcprint("[HeroSelection] HeroSelectionManagerImpl:OnTouchInterfaceChanged()")
    UGCTimerUtility.CreateLuaTimer(-1, function()
        UGCWidgetManagerSystem.SetVirtualJoystickVisibility(false)
    end)
end

function HeroSelectionManagerImpl:PurchaseHero(HeroID)
    assert(self.bInitialized)
    print("[HeroSelection] HeroSelectionManagerImpl:PurchaseHero(" .. tostring(HeroID) .. ")")
    HeroSelectionShopProxy:PurchaseHero(HeroID)
end

function HeroSelectionManagerImpl:StartDetectTouch()
    self.TimerHandle_CheckTouchMove = UGCTimerUtility.CreateLuaTimer(0.02, function() self:CheckTouchMove() end,true, "CheckTouchMove")
end

function HeroSelectionManagerImpl:StopDetectTouch()
    if self.TimerHandle_CheckTouchMove then
        UGCTimerUtility.RemoveLuaTimer(self.TimerHandle_CheckTouchMove)
    end
end

function HeroSelectionManagerImpl:CheckTouchMove()
    if self.curPos then
        self.prePos = {X = self.curPos.X, Y = self.curPos.Y}
    else
        self.prePos = Client.GetGestureLocation(0):Copy()
    end
    self.curPos = Client.GetGestureLocation(0):Copy()

    if not self.isTouching and (self.curPos.X > 0.01 or self.curPos.Y > 0.01) then
        self.isTouching = true
        self.startPos = {X = self.curPos.X, Y = self.curPos.Y}
        ugcprint("StartPos = "..self.curPos.X.." "..self.curPos.Y)
    end

    if self.isTouching then
        self:CheckIfSlide(self.startPos, self.curPos)
    end
end

function HeroSelectionManagerImpl:CheckIfSlide(startPos, endPos)
    local XOffset = (endPos.X - startPos.X)
    local YOffset = math.abs(endPos.Y - startPos.Y)
    -- 计算滑屏角度
    local atan = math.atan( YOffset, XOffset )
    local deg = math.deg(atan)

    if (self.curPos.X < 0.01 and self.curPos.Y < 0.01) then
        self.isTouching = false
    end

    -- TouchingMoveScaleX：两次检测的 滑动的距离差值 / 屏幕的总长度
    local TouchingMoveScaleX = XOffset / Client.GetViewportSize().X
    if TouchingMoveScaleX ~= 0 and math.abs(TouchingMoveScaleX) < 0.2 then
        if deg < 35 or deg > 145 then
            -- 更新英雄模型方向
            self:UpdateHeroMeshRotation(-TouchingMoveScaleX)
            self.isTouching = false
        end
    end
end

---更新英雄模型方向
---@param Scale number 滑动距离 / 屏幕总宽度
function HeroSelectionManagerImpl:UpdateHeroMeshRotation(Scale)
    local TargetMeshComp = self.HeroSelectionActor.SkeletalMesh
    local TargetRot = Rotator.New(0, Scale * 360, 0) -- todo @ magic number 360
    TargetMeshComp:K2_AddRelativeRotation(TargetRot)
end

-- 刷新 self 中缓存的对象状态
function HeroSelectionManagerImpl:UpdateCachedVariables()
    if self.HeroSelectionActor then

        self.AvatarPoseComponent_BP = self.HeroSelectionActor.AvatarPoseComponent_BP
        if self.AvatarPoseComponent_BP then
            self.LobbyPawn = self.AvatarPoseComponent_BP.LobbyPawn
            self.PlayerAvatar = self.AvatarPoseComponent_BP.PlayerAvatar
        else
            ugcprint("[HeroSelection] HeroSelectionManagerImpl:init(): AvatarPoseComponent_BP is nil")
        end

        self.PlayerController = UGCGameSystem.GetAllPlayerController()[1]
        if self.PlayerController then
            self.PlayerPawn = self.PlayerController:GetCurPawn();
            self.PlayerKey = self.PlayerController:GetInt64PlayerKey();
        else
            ugcprint("[HeroSelection] HeroSelectionManagerImpl:UpdateCacheVariables(): PlayerController is nil")
        end
    else
        ugcprint("[HeroSelection] HeroSelectionManagerImpl:UpdateCacheVariables(): HeroSelectionActor is nil")
    end
end

function HeroSelectionManagerImpl:HasAuthority()
    return self.PlayerController and self.PlayerController:HasAuthority()
end

function HeroSelectionManagerImpl:DumpHeroData()
    ugcprint("---------------------- DumpHeroData ----------------------")
    ---@param HeroData Hero
    for _, HeroData in pairs(self.HeroDataMap) do
        local DumpMsg = {
            HeroData = HeroData,
            HeroUI = self:GetUGCHeroUIData(HeroData.ID),
            HeroAbilityLabel = self:GetUGCHeroAbilityLabelData(HeroData.ID),
            HeroFreeConfig = self:GetUGCHeroFreeConfigData(HeroData.ID),
            NativeFuncResults = {
                IsFree = self:IsHeroFree(HeroData.ID),
                IsHeroPermanentFree = self:IsHeroPermanentFree(HeroData.ID),
                IsIsHeroTimeLimitedFree = self:IsHeroTimeLimitedFree(HeroData.ID),
                IsHeroPurchased = self:IsHeroPurchased(HeroData.ID),
                IsHeroLocked = self:IsHeroLocked(HeroData.ID),
            }
        }
        log_tree(DumpMsg)
    end
    ugcprint("---------------------- DumpHeroData ----------------------")
end

-- 将时间戳转换为 FDateTime
function ConvertToFDateTime(timestamp)
    -- 使用 os.date() 将时间戳转换为表
    local dateTable = os.date("*t", timestamp)

    -- 构造 FDateTime
    local FDateTime = KismetMathLibrary.MakeDateTime(dateTable.year, dateTable.month, dateTable.day, dateTable.hour, dateTable.min, dateTable.sec)

    return FDateTime
end

return HeroSelectionManagerImpl
